#!/usr/bin/env tsx
/**
 * Codegen: generate typed capability router map from .cap.ts definitions.
 *
 * Scans packages/types/src/capabilities/*.cap.ts, reads each exported
 * capability definition, and generates a TypeScript file with:
 *   - Import of each capability definition
 *   - A typed router map for the auto-mounted capability routers
 *
 * The generated file is consumed by trpc.router.ts to include capability
 * routers in the AppRouter with full type inference.
 *
 * Usage:
 *   npx tsx scripts/generate-capability-router-types.ts
 *
 * Run after adding/removing/modifying capability definitions.
 */

import * as fs from 'node:fs'
import { writeIfChanged } from './codegen-write.ts'
import * as path from 'node:path'

const ROOT = path.resolve(import.meta.dirname ?? __dirname, '..')
const CAPS_DIR = path.join(ROOT, 'packages/types/src/capabilities')
const OUTPUT_FILE = path.join(ROOT, 'packages/types/src/generated/capability-router-map.ts')

interface CapInfo {
  /** File name without extension (e.g., 'motion-detection.cap') */
  fileName: string
  /** Exported const name (e.g., 'motionDetectionCapability') */
  exportName: string
  /** Capability name from the definition (e.g., 'motion-detection') */
  capName: string
  /** Capability mode (singleton or collection) — source of truth is the cap definition */
  mode: 'singleton' | 'collection'
  /** Has methods? */
  hasMethods: boolean
  /** Has settings? */
  hasSettings: boolean
  /** camelCase key for the router map (e.g., 'motionDetection') */
  routerKey: string
}

function kebabToCamel(str: string): string {
  return str.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase())
}

function findCapabilities(): CapInfo[] {
  const files = fs.readdirSync(CAPS_DIR).filter((f) => f.endsWith('.cap.ts'))
  // Map keyed by cap name so we can dedupe across files. The legacy aggregate
  // files (`detection.cap.ts`, `infra.cap.ts`, `providers.cap.ts`) duplicate
  // many caps that already live in dedicated `${capName}.cap.ts` files; we
  // prefer the dedicated file when the same cap appears in both.
  const byName = new Map<string, CapInfo>()

  for (const file of files) {
    const content = fs.readFileSync(path.join(CAPS_DIR, file), 'utf-8')

    // Find every: export const xxxCapability = { name: 'yyy', ... }
    // Use matchAll so multi-cap aggregate files contribute every cap they
    // declare instead of only the first one.
    const exportMatches = [
      ...content.matchAll(
        /export\s+const\s+(\w+Capability)\s*=\s*\{[\s\S]*?name:\s*['"]([^'"]+)['"][\s\S]*?mode:\s*['"](singleton|collection)['"]/g,
      ),
    ]

    for (const match of exportMatches) {
      const exportName = match[1]!
      const capName = match[2]!
      const mode = match[3] as 'singleton' | 'collection'

      // Use a per-cap content slice for hasMethods/hasSettings detection so
      // multi-cap aggregates don't accidentally reuse signals from siblings.
      const startIdx = match.index ?? 0
      // Heuristic block bound: until the next `export const` or end of file.
      const nextExport = content.indexOf('\nexport const ', startIdx + 1)
      const blockEnd = nextExport === -1 ? content.length : nextExport
      const block = content.slice(startIdx, blockEnd)
      const hasMethods = block.includes('methods:')
      const hasSettings = block.includes('settings:')

      const fileName = file.replace('.ts', '')
      const dedicatedFileName = `${capName}.cap`

      const candidate: CapInfo = {
        fileName,
        exportName,
        capName,
        mode,
        hasMethods,
        hasSettings,
        routerKey: kebabToCamel(capName),
      }

      const existing = byName.get(capName)
      if (!existing) {
        byName.set(capName, candidate)
        continue
      }

      // Prefer the dedicated `${capName}.cap.ts` file over an aggregate file.
      if (existing.fileName !== dedicatedFileName && fileName === dedicatedFileName) {
        byName.set(capName, candidate)
      }
      // Otherwise keep the existing entry — silently ignores aggregate dups.
    }
  }

  return [...byName.values()].sort((a, b) => a.capName.localeCompare(b.capName))
}

function generate(): void {
  const caps = findCapabilities()

  console.log(`Found ${caps.length} capability definitions:`)
  for (const cap of caps) {
    console.log(
      `  ${cap.capName} → ${cap.routerKey} (methods: ${cap.hasMethods}, settings: ${cap.hasSettings})`,
    )
  }

  const lines: string[] = [
    '// AUTO-GENERATED by scripts/generate-capability-router-types.ts — DO NOT EDIT',
    '// Re-run after adding/modifying capability definitions.',
    '//',
    `// Capabilities: ${caps.length}`,
    '/* eslint-disable */',
    '',
    '// ── Capability Definition Imports ────────────────────────────────────',
    '',
  ]

  // Import each capability
  for (const cap of caps) {
    lines.push(`export { ${cap.exportName} } from '../capabilities/${cap.fileName}.js'`)
  }

  lines.push('')
  lines.push('// ── Capability Names (for registry key constants) ────────────────────')
  lines.push('')
  lines.push('export const CAPABILITY_NAMES = {')
  for (const cap of caps) {
    lines.push(`  ${cap.routerKey}: '${cap.capName}' as const,`)
  }
  lines.push('} as const')

  lines.push('')
  lines.push('/** All known capability names. */')
  lines.push('export type CapabilityName = typeof CAPABILITY_NAMES[keyof typeof CAPABILITY_NAMES]')

  lines.push('')
  lines.push('/** Router key → capability name mapping for auto-mount. */')
  lines.push(
    'export const CAPABILITY_ROUTER_KEYS: ReadonlyArray<{ readonly key: string; readonly name: string }> = [',
  )
  for (const cap of caps.filter((c) => c.hasMethods)) {
    lines.push(`  { key: '${cap.routerKey}', name: '${cap.capName}' },`)
  }
  lines.push(']')

  // ── CapabilityRouterMap type for typed AppRouter spread ──
  lines.push('// ── Typed Router Map (for AppRouter) ─────────────────────────────────')
  lines.push('//')
  lines.push('// Import CapabilityTRPCRouter from the server to type the map.')
  lines.push('// This type is consumed by trpc.router.ts for typed spread.')
  lines.push('')
  lines.push('/**')
  lines.push(' * Map of {name} → TRouter for typed AppRouter spread.')
  lines.push(' * Generic TRouter defaults to unknown — the server layer resolves it')
  lines.push(' * to the generated capability router type.')
  lines.push(' */')
  lines.push('export interface CapabilityRouterMap<TRouter = unknown> {')
  for (const cap of caps.filter((c) => c.hasMethods)) {
    lines.push(`  readonly ${cap.routerKey}: TRouter`)
  }
  lines.push('}')
  lines.push('')

  // ── Singleton/Collection name constants ─────────────────────────────
  // Mode is the single source of truth, declared inside the .cap.ts
  // CapabilityDefinition. The generator splits the caps into two tuples
  // that downstream packages use to derive typed `SingletonCapabilityMap`
  // and `CollectionCapabilityMap` via intersection with the hand-curated
  // `CapabilityProviderMap`. This enables hard-typed registry getters:
  //   registry.getSingleton<'stream-broker'>(name)  // OK
  //   registry.getSingleton<'decoder'>(name)        // TS error (collection)
  //   registry.getCollection<'decoder'>(name)       // OK
  //
  // Session 5 Sprint A5 introduced this — see audit addendum finding R6.
  lines.push('// ── Singleton / Collection split (derived from cap.mode) ─────────────')
  lines.push('')
  const singletonCaps = caps.filter((c) => c.mode === 'singleton')
  const collectionCaps = caps.filter((c) => c.mode === 'collection')
  lines.push(`/** Capability names whose mode is \`singleton\` (${singletonCaps.length} caps). */`)
  lines.push('export const SINGLETON_CAPABILITY_NAMES = [')
  for (const cap of singletonCaps) {
    lines.push(`  '${cap.capName}',`)
  }
  lines.push('] as const')
  lines.push('')
  lines.push('/** Union of singleton capability names (literal string union). */')
  lines.push('export type SingletonCapabilityName = typeof SINGLETON_CAPABILITY_NAMES[number]')
  lines.push('')
  lines.push(
    `/** Capability names whose mode is \`collection\` (${collectionCaps.length} caps). */`,
  )
  lines.push('export const COLLECTION_CAPABILITY_NAMES = [')
  for (const cap of collectionCaps) {
    lines.push(`  '${cap.capName}',`)
  }
  lines.push('] as const')
  lines.push('')
  lines.push('/** Union of collection capability names (literal string union). */')
  lines.push('export type CollectionCapabilityName = typeof COLLECTION_CAPABILITY_NAMES[number]')
  lines.push('')
  lines.push('/** Capability mode lookup at runtime — mirrors the `.cap.ts` definitions. */')
  lines.push(
    "export const CAPABILITY_MODE: Readonly<Record<string, 'singleton' | 'collection'>> = {",
  )
  for (const cap of caps) {
    lines.push(`  '${cap.capName}': '${cap.mode}',`)
  }
  lines.push('}')
  lines.push('')

  // ── ALL_CAPABILITY_DEFINITIONS — bulk array for boot-time declaration ─
  //
  // The hub's CapabilityRegistry needs every CapabilityDefinition declared
  // before addons (in-process or worker-side via the Moleculer bridge)
  // call `registerProvider`. Hand-curating that list in `main.ts` invites
  // the exact bug we keep hitting: a new cap ships, the addon registers
  // its provider, the hub silently drops it because the cap was never
  // declared. Iterating this generated array makes "add a new cap" a
  // single-file change (the .cap.ts file itself).
  lines.push('// ── All Capability Definitions (for boot-time declaration) ───────────')
  lines.push('')
  lines.push("import type { CapabilityDefinition } from '../capabilities/capability-definition.js'")
  for (const cap of caps) {
    lines.push(
      `import { ${cap.exportName} as _${cap.exportName} } from '../capabilities/${cap.fileName}.js'`,
    )
  }
  lines.push('')
  lines.push('/**')
  lines.push(' * Every CapabilityDefinition shipped by `@camstack/types`. The hub')
  lines.push(' * iterates this array at boot to declare each cap on the registry')
  lines.push(' * before addons (in-process or via the Moleculer bridge) attempt')
  lines.push(' * `registerProvider`. Adding a new cap means dropping a `*.cap.ts`')
  lines.push(' * file in `packages/types/src/capabilities/` and re-running')
  lines.push(' * `npx tsx scripts/generate-capability-router-types.ts` — no manual')
  lines.push(' * edit to `main.ts` required.')
  lines.push(' */')
  lines.push('export const ALL_CAPABILITY_DEFINITIONS: readonly CapabilityDefinition[] = [')
  for (const cap of caps) {
    lines.push(`  _${cap.exportName} as CapabilityDefinition,`)
  }
  lines.push(']')
  lines.push('')

  const output = lines.join('\n') + '\n'

  fs.mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true })
  writeIfChanged(OUTPUT_FILE, output)
  console.log(`\nWritten to: ${path.relative(ROOT, OUTPUT_FILE)}`)
  console.log(
    `  ${caps.length} capabilities, ${caps.filter((c) => c.hasMethods).length} with auto-mounted routers`,
  )
}

generate()
